        EXTI->IMR |= (1 << 13);

    // Configure PA2 and PA3 as Alternate Function (Mode 10)
    GPIOA->MODER &= ~((3U << 4) | (3U << 6));
    GPIOA->MODER |=  ((2U << 4) | (2U << 6));

